import { TokenType } from './token-type';
/**
 * Part of the suggestion.
 */
export interface AutocompleteSuggestionPart {
    type: TokenType;
    /**
     * The type of the suggestion.
     */
    info?: string;
    /**
     * The synopsis of the suggestion.
     */
    synopsis?: string;
    /**
     * The suggested continuation of the query.
     */
    suggestion: string;
}
